import json,re,hashlib
from pathlib import Path
from html import unescape
from xml.etree import ElementTree as ET
s=json.loads(Path('source.json').read_text());a=json.loads(Path('answer.json').read_text());r=json.loads(Path('reference-targets.json').read_text())
def plain(x):return re.sub(r'\\s+',' ',unescape(re.sub(r'<["'^>]*>'"',' ',x))).strip()
errors=[]
for x,y in zip(s,a):
 n=x['number']
 for k in ['code_id','source_id','source_sha256','number']:
  if x[k]"'!=y[k]:errors.append((n,k,'"'identifiant'))
 if y['status']=='retained_unchanged':
  assert y['proposed_xml'] is None
  assert y['substantive_impact']['classification']=='retained_necessary'
  assert y['substantive_impact']['effects']==[]
 else:
  try:
   el=ET.fromstring('<root>'+y['proposed_xml']+'</root>')
   for e in el.iter():
    assert e.tag in ['root','p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote']
    for k,v in e.attrib.items():assert k in ['rowspan','colspan'] and v.isnumeric()
  except Exception as e:errors.append((n,'xml',str(e)))
 z=y['substantive_impact']
 assert z['version']==1
 for k in ['assessment','scope_limitations','new_burdens_review']:
  if len(z[k])<40:errors.append((n,k,'court'))
 for e in z['effects']:
  if not re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) or not 6<=len(e['measure_id'])<=96:errors.append((n,'measure_id',e['measure_id']))
  for k,txt in [('source_quote',plain(x['source_xml'])),('proposed_quote',plain(y['proposed_xml']))]:
   if len(e[k])<12 or e[k] not in txt:errors.append((n,k,e[k]))
 if x['benefit_check_required'] and len(y.get('benefit_review',''))<100:errors.append((n,'benefit_review','court'))
 if y.get('change_type')=='normative_reduction':
  assert y['reform_policy_id']=='editorial_direction_2026_10_19'
  assert all(len(v)>=30 for v in y['removed_provisions'])
 rk=x['code_id']+'|'+x['source_id']
 found={q['target_key'] for q in y['reference_checks']}
 if not set(r['requirements'][rk])<=found:errors.append((n,'cibles manquantes'))
 for q in y['reference_checks']:
  if q['view_sha256']"'!=r['"'targets'][q['target_key']]['view_sha256'] or len(q['assessment'])<80:errors.append((n,'reference_checks',q))
 print(n,y['status'],z['classification'],'effets',len(z['effects']),'cibles',len(y['reference_checks']))
assert len(a)==len(s)==12
print('ERREURS',json.dumps(errors,ensure_ascii=False,indent=2))
print('Taille',Path('answer.json').stat().st_size)
PY"

